Where does toast appear? Gravity toaster appears bottom-right by default — matches "в углу". Button in corner too. I'll place the button bottom-right, toast also bottom-right. Fine.

Since useToaster must be called inside ToasterProvider, structure:

```tsx
import {Button, Toaster, ToasterComponent, ToasterProvider, useToaster} from '@gravity-ui/uikit';

const toaster = new Toaster();

function CornerButton() {
  const {add} = useToaster();
  const counterRef = useRef(0);
  return (
    <Button
      view="action"
      size="l"
      style={{position: 'fixed', right: 'var(--g-spacing-6)', bottom: 'var(--g-spacing-6)'}}
      onClick={() => {
        counterRef.current += 1;
        add({
          name: `toast-${counterRef.current}`,
          title: 'Уведомление',
          content: 'Кнопка нажата — это сообщение исчезнет само.',
          theme: 'success',
          autoHiding: 5000,
        });
      }}
    >
      Показать уведомление
    </Button>
  );
}

export function App() {
  return (
    <ToasterProvider toaster={toaster}>
      <CornerButton />
      <ToasterComponent />
    </ToasterProvider>
  );
}
```

